  'audit.validationTitle': 'Validación auditoría AI',
  'audit.validationPrompt': 'Aquí está la documentación del proyecto (carpeta docs/). Sigue el protocolo estricto de validación en 4 fases. NO emitas KRONN:VALIDATION_COMPLETE hasta que las 4 fases estén completas.\n\n## Fase 1 — Auto-corrección (autónoma)\nLee el código fuente y corrige lo que puedas: marcadores TODO huérfanos, archivos esqueleto, info desactualizada. Actualiza los archivos docs/ directamente.\n\n## Fase 2 — Preguntas de ambigüedad (interactiva)\nHaz tus preguntas una por una. Con cada respuesta, actualiza los archivos docs/ antes de la siguiente pregunta. Si una respuesta revela nuevas incógnitas, haz preguntas de seguimiento.\n\n## Fase 3 — Revisión deuda técnica (interactiva)\nRevisa CADA entrada de docs/inconsistencies-tech-debt.md y docs/tech-debt/. Para cada item: ¿es correcta la evaluación? ¿Qué prioridad? ¿Crear un ticket?\n\n## Fase 4 — Desafío documentación (interactiva)\nHazme 2-3 preguntas prácticas que un dev nuevo haría. Verifica si la doc las responde. Si insuficiente, actualiza y haz otra pregunta.\n\nSolo cuando las 4 fases estén completas, termina con: "KRONN:VALIDATION_COMPLETE".',
