  'settings.recovery.title': 'Frase de recuperación',
  'settings.recovery.hint': 'Protege la clave que cifra tus secretos de plugins (tokens API). Elige una frase abajo: Kronn genera entonces un código de recuperación, mostrado una sola vez, para guardar fuera de esta máquina (gestor de contraseñas). Si la clave se pierde algún día (config sobrescrita, keychain restablecido, reinstalación), tu frase — junto con ese código si el directorio de datos también desapareció — restaura el acceso a tus secretos.',
  'settings.recovery.configured': 'Configurada',
