  'settings.bioInfoInjection': 'Kronn inyecta la biografía únicamente cuando inicia por sí mismo el agente de una conversación, y solo en el primer intercambio. Esto incluye un agente CLI seleccionado como agente de la conversación.',
  'settings.bioInfoCli': 'No se inyecta en un CLI utilizado directamente o unido a la conversación mediante MCP, ni en los steps Agente de un workflow. En modo full CLI, este campo no tiene ningún efecto.',
  'settings.bioPlaceholder': 'Ej: Product Manager en Acme Corp, especializado en analytics y growth...',
