  'settings.clDesc': 'Los agentes pueden proponer convenciones, preferencias y trampas duraderas. Debes validar cada propuesta antes de que Kronn la escriba en la documentación dedicada.',
  'settings.clToggleLabel': 'Activar el aprendizaje continuo',
  'settings.clHint': 'Una vez activado, la herramienta MCP learning_propose está disponible y Kronn enlaza los proyectos compatibles con docs/learnings.md. Desactivarlo detiene nuevas propuestas y elimina ese enlace sin borrar los aprendizajes validados.',
  'settings.clRiskTitle': 'Advertencia — función experimental',
  'settings.clRiskBody': 'La activación modifica la documentación de tus proyectos: Kronn añade un bloque técnico a docs/AGENTS.md y crea o actualiza docs/learnings.md tras validación humana. Este mecanismo sigue siendo experimental. Utilízalo preferiblemente en proyectos respaldados y versionados; al desactivarlo se conserva el archivo de aprendizajes ya creado.',
  'settings.clSaved': 'Aprendizaje continuo actualizado.',
  'settings.clSaveError': 'Error al actualizar el aprendizaje continuo.',
  'settings.sourcingIntro': 'Kronn encuadra las afirmaciones de los agentes con una convención de citación y señala las fuentes ausentes o inválidas. El alcance exacto depende de cómo esté conectado el agente a Kronn.',
  'settings.sourcingScopeTitle': '¿Qué agentes están cubiertos?',
  'settings.sourcingScopeLaunched': 'Los agentes iniciados por Kronn reciben la instrucción de citar sus fuentes y después se comprueban sus respuestas.',
  'settings.sourcingScopeExternal': 'Un agente externo unido mediante MCP puede no recibir la instrucción, pero los mensajes que publica en Kronn pueden comprobarse después. Un CLI utilizado completamente fuera de Kronn no está cubierto.',
  'settings.sourcingModeLabel': 'Modo de control',
  'settings.sourcingSpecToggle': 'Ver la spec completa (Kronn AGENTS.md v1)',
  'settings.sourcingSpecHint': 'Convención técnica aplicada por esta instalación de Kronn.',
