  'settings.sourcingSpecError': 'No se pudo cargar la spec local. Verifica que la API de Kronn esté accesible.',
  'settings.ahExplainOff': 'no se inyecta directiva, no hay análisis, no hay etiqueta. Los agentes responden sin restricción de sourcing.',
  'settings.ahExplainWarn': 'los agentes iniciados por Kronn reciben la instrucción de citar sus fuentes (`archivo:línea`, URL o «user-confirmed»). Kronn comprueba las citas accesibles y muestra una etiqueta cuando falta una fuente o parece inválida. Nada se bloquea.',
  'settings.ahExplainEnforce': 'rechaza las citas `[src:]` fabricadas. En una auditoría el paso se reintenta (hasta 3×) y luego falla limpiamente en vez de escribir una doc con citas inventadas; en una discusión, una respuesta con una cita fabricada se conserva pero se señala para corregir.',
