  'mcp.drift.never': '{0} llamadas a `{1}` fallaron ({2}) y ninguna ha tenido éxito — este endpoint probablemente no existe o ya no existe. Revisa la spec del plugin.',
  'mcp.drift.sometimes': '{0} llamadas a `{1}` fallaron ({2}), pero otras sí funcionan — el endpoint existe; son los parámetros declarados los que no coinciden.',
  'mcp.custom.helper.sys.verify': 'VERIFICA ANTES DE AFIRMAR — la documentación de una API suele mentir: nombres de parámetros obsoletos, endpoints eliminados, paginación no documentada. Una spec inventada hace que los agentes pierdan horas. Si puedes ejecutar comandos Y el usuario ha proporcionado credenciales, prueba CADA endpoint con una llamada real (curl) antes de declararlo, y no declares ninguno que no hayas visto responder. Tres trampas: (1) un parámetro desconocido suele aceptarse e IGNORARSE en silencio — un 200 no prueba que el filtro se aplicó, compara un campo discriminante de la respuesta con lo que pediste; (2) anota en la descripción la FORMA de la respuesta cuando está paginada o envuelta (`{data:[…], meta}`) y los nombres exactos de los parámetros que funcionan; (3) indica si una entrada es voluminosa, para que un agente proyecte solo los campos necesarios. Lo que NO hayas podido verificar, prefíjalo con `❔ sin verificar:` — nunca lo afirmes.',
  'mcp.custom.helper.sys.style': 'Mantente conciso. Haz una pregunta a la vez si necesitas clarificar. Indica siempre qué falta para finalizar la config.',
  'mcp.custom.helper.sys.starter': 'Hola! Describe la API que quieres configurar: pega un curl, un enlace de docs, o explica en lenguaje natural.',
  'mcp.custom.helper.sys.userQuestion': '=== PREGUNTA USUARIO ===',
