  'wiz.helpSimpleVsAdvanced': 'Simple = 1 paso, 1 agente, 1 tarea (ej: "genera un informe semanal"). Avanzado = pipelines multi-paso con condiciones (ej: "recupera tickets → batch → notificar"). Siempre puedes cambiar a Avanzado más tarde.',
