  'wiz.helpAgent': 'El modelo IA que ejecutará la tarea. Claude Code suele ser el más capaz; Codex y Gemini son alternativas. Cada agente debe instalarse por separado en tu máquina.',
  'wiz.promptLabel': '¿Qué debe hacer el agente?',
  'wiz.helpPromptSimple': 'Describe la tarea en lenguaje natural, como si hablaras con un compañero. Puedes usar variables como {{issue.title}} si el workflow se activa por una issue del tracker.',
