  'wiz.helpStarters': 'Haz clic en un ejemplo para pre-rellenar el nombre y el prompt. Puedes editarlos libremente antes de guardar.',
  'wiz.starter.codeReview': 'Revisión de código',
  'wiz.starter.codeReviewPrompt': 'Analiza los últimos commits en la rama principal. Para cada archivo modificado, identifica:\n- Problemas de calidad (código duplicado, complejidad excesiva)\n- Fallas de seguridad potenciales\n- Violaciones de convenciones del proyecto\n\nGenera un informe Markdown con los problemas clasificados por severidad (crítico / atención / sugerencia).',
  'wiz.starter.changelog': 'Changelog automático',
  'wiz.starter.changelogPrompt': 'Analiza todos los commits desde el último tag de release. Para cada commit, identifica si es una nueva funcionalidad, corrección, mejora o cambio técnico.\n\nGenera un changelog Markdown estructurado con secciones: Novedades, Correcciones, Mejoras, Técnico.',
  'wiz.starter.techDebt': 'Detección deuda técnica',
  'wiz.starter.techDebtPrompt': 'Escanea el código fuente del proyecto e identifica elementos de deuda técnica:\n- TODO/FIXME/HACK restantes en el código\n- Dependencias obsoletas o con vulnerabilidades conocidas\n- Archivos de más de 500 líneas sin tests\n- Código muerto o imports no utilizados\n\nGenera un informe priorizado con el esfuerzo estimado (S/M/L) para cada elemento.',
  'wiz.starter.testCoverage': 'Auditoría cobertura tests',
  'wiz.starter.testCoveragePrompt': 'Analiza la estructura del proyecto e identifica archivos y funciones críticas sin tests:\n- Endpoints API sin test de integración\n- Funciones utilitarias sin test unitario\n- Componentes UI con interacciones sin test\n\nGenera una lista priorizada de los tests faltantes más importantes, con un esqueleto de test para cada uno.',
  'wiz.starter.docUpdate': 'Actualización documentación',
  'wiz.starter.docUpdatePrompt': 'Compara la documentación existente (README, docs/, comentarios) con el código actual. Identifica:\n- Secciones obsoletas o incorrectas\n- Nuevas funcionalidades no documentadas\n- Instrucciones de instalación o configuración a actualizar\n\nPropone las correcciones para cada archivo.',
  'wiz.starter.securityScan': 'Escaneo seguridad',
  'wiz.starter.securityScanPrompt': 'Realiza una auditoría de seguridad del proyecto:\n- Verifica dependencias para CVE conocidas\n- Busca secretos o tokens hardcodeados en el código\n- Identifica inyecciones potenciales (SQL, XSS, command injection)\n- Verifica permisos y configuración de autenticación\n\nGenera un informe con vulnerabilidades clasificadas por criticidad (CRITICAL / HIGH / MEDIUM / LOW).',
