  'wiz.gateTitle': 'Pausa humana (Gate)',
  'wiz.gateHint': 'El run se detiene en este paso esperando una decisión (aprobar, solicitar cambios, rechazar). Templates {{steps.X.summary}} soportados en el mensaje.',
