  'wiz.batchQPTitle': 'Batch Quick Prompt',
  'wiz.batchQPHint': 'Ejecuta un Quick Prompt en cada ítem de una lista producida por un paso anterior (Jira, GitHub, etc.). Por defecto, el workflow espera a que terminen todas las discusiones hijas.',
  'wiz.batchQPNoQPs': 'No hay Quick Prompts disponibles. Crea uno primero en la pestaña Quick Prompts.',
  'wiz.batchQPPicker': 'Quick Prompt a lanzar',
  'wiz.batchQPPickerEmpty': 'elige un QP',
  'wiz.notifyMissingUrl': 'URL del webhook faltante',
