  'wiz.batchQPVarSubst': 'Cada ítem de la lista llenará la variable {{{0}}} del Quick Prompt.',
  'wiz.batchItemsFrom': 'Lista de ítems a procesar',
  'wiz.batchItemsFromRequired': 'Indica dónde encontrar la lista — normalmente el output de un paso anterior.',
  'wiz.batchItemsFromHelper': 'Haz clic en un paso anterior para autocompletar:',
  'wiz.batchItemsFromFromStep': '← Desde {0}',
  'wiz.batchItemsFromPickStep': 'Usar el output del paso "{0}"',
  'wiz.batchFirstStepWarning': 'Un paso batch en primera posición no tiene paso anterior para encadenar. Añade un paso "fetch" antes para obtener la lista, o codifica la lista directamente en el campo de abajo.',
  'wiz.batchAutoPrevNotice': '↑ Paso « {name} » auto-configurado para alimentar este batch',
  'wiz.batchWaitForCompletion': 'Esperar a que terminen todas las discusiones',
  'wiz.batchMaxItems': 'Máx ítems',
  'wiz.batchWorktree': 'Aislar los cambios de cada agente',
  'wiz.batchWorktreeHint': 'Cada agente trabaja en su propia copia del proyecto para no sobrescribir el trabajo de los demás. Marque si los agentes van a modificar archivos en paralelo. Deje desmarcado para análisis (informes, auditorías) — es más rápido.',
  'wiz.batchWorktreeNoProject': 'Este Quick Prompt no está vinculado a ningún proyecto — no hay código que aislar.',
  'wiz.batchChain': 'Encadenar más Quick Prompts (opcional)',
  'wiz.batchChainHint': 'Después del QP inicial, estos QPs se enviarán secuencialmente como mensajes de usuario en CADA discusión batch. Cada QP recibe el MISMO ítem del batch (ej: "EW-1234") en su primera variable — ideal para "análisis → review → resumen" sobre el mismo ticket. También puedes reutilizar la respuesta del agente anterior con `{{previous_qp.output}}` para flujos "brief → plan → tickets". Los QPs con 2+ variables no son elegibles. El batch solo se marca como completado cuando cada cadena termina.',
  'wiz.batchChainAdd': '+ Añadir un QP a la cadena',
  'wiz.batchChainRemove': 'Quitar de la cadena',
  'wiz.batchChainMoveUp': 'Subir en la cadena',
  'wiz.batchChainMoveDown': 'Bajar en la cadena',
  'wiz.batchChainEmpty': 'No hay QP sin variables disponible para encadenar.',
  'wiz.stepDescription': 'Descripción',
  'wiz.stepDescriptionPlaceholder': '¿Qué hace este step en 1 línea? Ej. «Obtiene los tickets Jira abiertos» o «Analiza los logs de tests» — mostrado en la lista, opcional.',
  'wiz.insertStepHere': 'Insertar un step aquí',
  'wiz.moveStepUp': 'Subir este step',
  'wiz.moveStepDown': 'Bajar este step',
  'wiz.ifContainsPlaceholder': 'Palabra clave a buscar en la salida del agente (ej. APPROVED, NEEDS_CHANGES, ERROR…)',
  'wiz.removeCondition': 'Eliminar esta condición',
  'wiz.wfVariablesTitle': 'Variables de lanzamiento',
  'wiz.wfVariablesHint': 'Variables solicitadas al lanzar manualmente — como los Quick Prompts. Los valores se convierten en `{{nombre}}` en tus step prompts. Opcional — déjalo vacío si tu workflow obtiene su contexto desde un step previo (ApiCall) o un trigger.',
